(() => {
 const $=id=>document.getElementById(id),e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),url=(type,id)=>'#'+type+'/'+encodeURIComponent(id);
 const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
 const data=anansiFrontend.normalize(anansiFrontend.read()||{artists:[],works:[],shows:[],leads:[]});
 const study={id:'demo-tidal',title:'Tidal Intervals',description:'A study in quiet movement. Three views of water, weather and the traces they leave behind. This illustrative exhibition invites you to slow down and look a little longer.',status:'Presentation study',demo:true};
 const collection={id:'demo-collection',name:'Anansi presentation collection',bio:'These AI-generated studies illustrate how artwork and artist stories will appear at Anansi. They are not submissions by a real artist and are not offered for sale.',demo:true};
 const demo=[0,1,2].map(i=>({id:'demo-panel-'+i,name:'Tidal Intervals / '+(i+1),artist:collection.name,artistId:collection.id,show:study.title,showId:study.id,format:'Painting',panel:i,image:'assets/tidal-intervals.png',story:['The shore is a threshold: never quite land, never quite water. This first interval looks at the marks left by a moving tide.','A pale horizon holds the room still. In the second interval, layers of water and atmosphere become a record of passing time.','The tide recedes, but its memory stays. The final interval gathers warm earth and cool water into one quiet surface.'][i]+'\n\nAI-generated presentation artwork, not a real artist submission.',price:'Presentation · not for sale',demo:true}));
 const works=[...demo,...data.works.filter(w=>w.placement!=='Storage / unplaced'&&anansiFrontend.visible(w,data))],shows=[study,...data.shows.filter(s=>s.status!=='Draft')],artists=[collection,...data.artists.filter(a=>works.some(w=>w.artistId===a.id||w.artist===a.name))];let selected=null;
 const saved=work=>{const list=read('anansiSavedWorks',[]);return list.includes(work.id)||list.includes(work.name)};
 function art(work){if(Number.isInteger(work.panel))return `<div class="art-image panel" role="img" aria-label="${e(work.name)}" style="background-position:${work.panel*50}% center"></div>`;if(work.image&&/^(data:image\/(png|jpeg|webp);base64,|https?:\/\/|assets\/)/i.test(work.image))return `<div class="art-image"><img src="${e(work.image)}" alt="${e(work.name)}" loading="lazy"></div>`;return `<div class="art-image art-placeholder"><span>${work.format==='Sculpture'?'3D sculpture<br>View its model inside the gallery':'Artwork image not supplied'}</span></div>`}
 const cards=list=>list.length?list.map(w=>`<a class="work-card" href="${url('work',w.id)}">${art(w)}<div class="work-caption"><div><h3>${e(w.name)}</h3><p>${e(w.artist)}</p></div></div></a>`).join(''):'<p class="empty">No works here yet. Try another filter or explore an exhibition.</p>';
 const pageTitle=(label,title,desc='')=>`<section class="page-title"><p class="eyebrow">${label}</p><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</section>`;
 function home(){return `<section class="hero-copy"><div><p class="eyebrow">A space for art & discovery</p><h1>A place for things<br>that remain.</h1></div><div class="hero-intro"><p>Some things ask for more than a glance.<br>A work. A story. A moment that stays.</p><a class="text-link" href="#exhibitions">Explore the exhibitions</a></div></section><figure class="hero-image"><img src="assets/gallery-hero.png" alt="The light-filled Anansi gallery concept, with a curved staircase and an open exhibition atrium" fetchpriority="high"><figcaption class="image-caption"><span>THE VIRTUAL GALLERY</span><a href="gallery.html">Come in. Take your time.</a></figcaption></figure><section class="section"><div class="section-heading"><p class="eyebrow">On view · presentation edition</p><a class="text-link" href="#exhibitions">All exhibitions</a></div><div class="feature"><a href="${url('exhibition',study.id)}" aria-label="Explore Tidal Intervals">${art(demo[1])}</a><div class="feature-copy"><p class="eyebrow">01 / Featured exhibition</p><h2>Tidal<br>Intervals</h2><p>Water moves. Memory settles. A quiet exploration of the landscapes that linger after we leave them.</p><div class="meta"><span>Painting · three studies</span><span>Illustrative exhibition</span></div><a class="button secondary" href="${url('exhibition',study.id)}">Discover the exhibition</a></div></div></section><section class="manifesto"><p class="eyebrow">The idea behind Anansi</p><div><h2>Not just a place to see art.<br>A place to spend time with it.</h2><p>Read the story behind a work. Find a new perspective. Walk through a gallery that makes room for curiosity.</p><a class="text-link" href="#about">A little about us</a></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">From the collection</p><h2>Look a little closer.</h2></div><a class="text-link" href="#works">All artworks</a></div><div class="work-grid">${cards(demo)}</div></section><section class="section visit-section"><div><p class="eyebrow">Beyond the frame</p><h2>A gallery.<br>Wherever you are.</h2><p>Step into the virtual space, choose your look and explore at your own pace. Prefer to keep things simple? Every story is right here on the website, too.</p><div class="actions"><a class="button" href="gallery.html">Enter the gallery</a><a class="text-link" href="#works">Browse without 3D</a></div><p class="local-note" style="margin-top:20px">The architecture shown is our gallery concept. The interactive presentation may vary by device.</p></div><img src="assets/gallery-hero.png" alt="The gallery's curved staircase and glazed upper promenade" loading="lazy"></section>`}
 function worksPage(onlySaved=false){return pageTitle('The collection',onlySaved?'Things you saved.':'Art, at your own pace.',onlySaved?'Your saved works stay on this browser.':'Paintings, sculptures, and the stories that make them more than objects.')+`<div class="filters"><input id="workSearch" type="search" aria-label="Search artwork or artist" placeholder="Search artwork or artist"><select id="showFilter" aria-label="Filter by exhibition"><option value="">All exhibitions</option>${shows.map(s=>`<option value="${e(s.id)}">${e(s.title)}</option>`).join('')}</select></div><p class="results-note" id="results" role="status"></p><section class="section collection"><div class="work-grid" id="workGrid"></div></section>`}
 function bindWorks(onlySaved){const filter=()=>{const q=$('workSearch').value.trim().toLowerCase(),show=$('showFilter').value,list=works.filter(w=>(!onlySaved||saved(w))&&(!show||w.showId===show)&&(w.name+' '+w.artist).toLowerCase().includes(q));$('workGrid').innerHTML=cards(list);$('results').textContent=list.length+(list.length===1?' work':' works');bindImages()};$('workSearch').oninput=$('showFilter').onchange=filter;filter()}
 function exhibitions(){return pageTitle('Exhibitions','A new way of looking.','Explore the current presentation and exhibitions published from your curator workspace.')+`<section class="exhibition-list">${shows.map((s,i)=>`<a class="exhibition-row" href="${url('exhibition',s.id)}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${e(s.title)}</h3><p>${e(s.status)} · ${works.filter(w=>w.showId===s.id).length} works</p></div><p>${e(s.description||'An exhibition from the Anansi curator workspace.')}</p></a>`).join('')}</section>`}
 function exhibition(id){const show=shows.find(s=>s.id===id);if(!show)return missing();const list=works.filter(w=>w.showId===id);return pageTitle('Exhibition',e(show.title),e(show.description||'Discover the works selected for this exhibition.'))+`<section class="editorial"><p class="eyebrow">${e(show.status)}<br>${list.length} works</p><div class="actions"><a class="button" href="${show.demo?'gallery.html':'gallery.html?exhibition='+encodeURIComponent(show.id)}">Visit the exhibition</a><a class="text-link" href="#exhibitions">All exhibitions</a></div></section><section class="section collection"><div class="work-grid">${cards(list)}</div></section>`}
 function artistList(){return pageTitle('The artists','Meet the minds<br>behind the works.','Each work has a voice. Start with the person, the practice, and the story.')+`<section class="artist-list">${artists.map((a,i)=>`<a class="artist-row" href="${url('artist',a.id)}"><span class="artist-number">${String(i+1).padStart(2,'0')}</span><div><h3>${e(a.name)}</h3><p>${a.demo?'Illustrative collection · not a real artist':e(a.discipline||a.medium||'Artist roster')} · ${works.filter(w=>w.artistId===a.id||w.artist===a.name).length} works on view</p></div></a>`).join('')}</section>`}
 function artist(id){const a=artists.find(a=>a.id===id);if(!a)return missing();return pageTitle(a.demo?'Presentation collection':'Artist',e(a.name))+`<section class="editorial"><a class="text-link" href="#artists">All artists</a><div><p>${e(a.bio||a.story||'This artist’s biography has not been added yet. Explore their currently exhibited works below.')}</p>${a.location?`<p class="local-note">${e(a.location)}</p>`:''}</div></section><section class="section collection"><div class="work-grid">${cards(works.filter(w=>w.artistId===id||w.artist===a.name))}</div></section>`}
 function workPage(id){const w=works.find(w=>w.id===id);if(!w)return missing();selected=w;const show=shows.find(s=>s.id===w.showId);return `<section class="detail"><div><p class="breadcrumb"><a href="#works">Collection</a> / ${e(w.name)}</p>${art(w)}</div><div class="detail-copy"><a class="text-link" href="#works">Back to artworks</a><p class="eyebrow">${e(w.format||'Artwork')}${w.demo?' · Presentation study':''}</p><h1>${e(w.name)}</h1>${artists.some(a=>a.id===w.artistId)?`<a class="artist-link" href="${url('artist',w.artistId)}">${e(w.artist)}</a>`:`<p>${e(w.artist)}</p>`}<dl><div><dt>Exhibition</dt><dd>${show?`<a href="${url('exhibition',show.id)}">${e(show.title)}</a>`:e(w.show||'Not assigned')}</dd></div><div><dt>Price</dt><dd>${e(w.price||'Price on request')}</dd></div><div><dt>Availability</dt><dd>${w.demo?'Not for sale':e(w.status||'Contact curator')}</dd></div></dl><p class="story">${e(w.story||'The story of this work has not been added yet.')}</p><div class="actions"><button class="button" id="interestButton">Express interest</button><button class="button secondary" id="saveWork">${saved(w)?'Remove saved work':'Save work +'}</button></div><p class="local-note" id="saveStatus" role="status" style="margin-top:20px">Saved interests are local to this presentation, not purchase reservations.</p></div></section>`}
 function about(){return pageTitle('About Anansi','For the things<br>that stay with us.')+`<section class="editorial"><p class="eyebrow">Our curatorial idea</p><div><p>Anansi is being built as a space for art to be encountered, not simply scrolled past. A painting can hold a story. A sculpture can change as you move around it. A conversation can make you see both differently.</p><p>The website is the front door. The virtual gallery is an invitation to step further in: walk, look, sit, and take your time.</p><p>“A place for things that remain” is the thought at the heart of it all.</p><div class="actions"><a class="button secondary" href="#exhibitions">Explore exhibitions</a><a class="text-link" href="gallery.html">Visit the gallery</a></div></div></section><figure class="hero-image"><img src="assets/gallery-hero.png" alt="Anansi's architectural gallery concept" loading="lazy"></figure><section class="editorial" style="padding-top:65px"><p class="eyebrow">About this edition</p><div><p>This is a frontend presentation. Tidal Intervals is an AI-generated illustrative collection, not a real artist exhibition. Curator records on this browser appear alongside it when published.</p><p>Visitor avatars and chat replies in the gallery are simulated. Interests and uploaded files remain on this browser. There are no live purchases, accounts, or shared artist inboxes yet.</p><a class="text-link" href="demo.html">Explore the presentation modes</a></div></section>`}
 function missing(){return pageTitle('Not found','This story isn’t here yet.','The work may have been removed or its exhibition returned to draft.')+'<section class="section"><a class="button" href="#works">Back to the collection</a></section>'}
 function bindImages(){const heading=$('main').querySelector('h1');if(heading)document.title=heading.innerText.replace(/\s+/g,' ').trim()+' · Anansi';document.querySelectorAll('#main img').forEach(img=>img.onerror=()=>{const note=document.createElement('p');note.className='art-placeholder';note.textContent='Image unavailable on this device.';img.replaceWith(note)})}
 function updateSaved(){const count=works.filter(saved).length;$('savedLink').textContent='Saved works'+(count?' ('+count+')':'')}
 document.querySelector('.skip').onclick=event=>{event.preventDefault();$('main').focus();$('main').scrollIntoView()};
 function route(){let parts;try{parts=(location.hash.slice(1)||'home').split('/').map(decodeURIComponent)}catch{parts=['missing']}const [page,id]=parts;selected=null;const html=page==='home'?home():page==='works'||page==='saved'?worksPage(page==='saved'):page==='exhibitions'?exhibitions():page==='exhibition'?exhibition(id):page==='artists'?artistList():page==='artist'?artist(id):page==='work'?workPage(id):page==='about'?about():missing();$('main').innerHTML='<div class="page-enter">'+html+'</div>';document.title=(selected?selected.name:({home:'A place for things that remain',works:'Artworks',saved:'Saved works',artists:'Artists',exhibitions:'Exhibitions',about:'About'}[page]||'Explore'))+' · Anansi';document.querySelectorAll('#navigation a').forEach(a=>{const current=a.hash.slice(1)===(page==='work'?'works':page==='artist'?'artists':page==='exhibition'?'exhibitions':page);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('.site-header').classList.remove('open');$('menu').setAttribute('aria-expanded','false');if(page==='works'||page==='saved')bindWorks(page==='saved');if(selected){$('saveWork').onclick=()=>{const list=read('anansiSavedWorks',[]),next=saved(selected)?list.filter(key=>key!==selected.id&&key!==selected.name):[...list,selected.id];if(save('anansiSavedWorks',next)){$('saveWork').textContent=saved(selected)?'Remove saved work':'Save work +';$('saveStatus').textContent=saved(selected)?'Saved on this browser.':'Removed from your saved works.';updateSaved()}else $('saveStatus').textContent='Browser storage is unavailable. Nothing was saved.'};$('interestButton').onclick=()=>{$('interestWork').textContent=selected.name+' · '+selected.artist;$('displayName').value=read('anansiVisitor',{}).name||'';$('interestForm').hidden=false;$('interestStatus').textContent='';$('interestDialog').showModal()}}bindImages();updateSaved();window.scrollTo(0,0);$('main').focus({preventScroll:true})}
 $('menu').onclick=()=>{const open=document.querySelector('.site-header').classList.toggle('open');$('menu').setAttribute('aria-expanded',String(open))};$('closeInterest').onclick=()=>$('interestDialog').close();
 $('interestForm').onsubmit=event=>{event.preventDefault();if(!selected)return;const name=$('displayName').value.trim();if(!name){$('displayName').setCustomValidity('Enter a display name.');$('displayName').reportValidity();return}const guest=read('anansiVisitor',{id:crypto.randomUUID()});guest.id??=crypto.randomUUID();const latest=anansiFrontend.read()||data;latest.leads??=[];latest.leads.push({id:crypto.randomUUID(),visitorId:guest.id,name,workId:selected.id,interest:selected.name,message:$('message').value.trim(),status:'New',demo:true});if(save('anansiVisitor',guest)&&save('anansiData',latest)){$('interestForm').hidden=true;$('interestStatus').textContent='Your interest is saved on this browser. No real message has been sent.';$('message').value=''}else $('interestStatus').textContent='Browser storage is unavailable. Your enquiry could not be saved.'};$('displayName').oninput=()=>$('displayName').setCustomValidity('');window.addEventListener('hashchange',route);route();
})();
